INSERT INTO `site_settings` (`site_id`, `key`, `value`, `created_at`, `updated_at`) VALUES (@site_id, 'homepage_content', '{"hero":{"kicker":"We''re Getting Married","names":"Kyle & Nicole","dateLine":"12 September, 2026","locationLine":"Kingfisher Country Estate, Templepatrick","buttonLabel":"RSVP Now","image":"\\/images\\/wedding\\/uploads\\/hero-image-20260414185405.jpeg","imageFocusX":50,"imageFocusY":50},"welcome":{"heading":"Dear Family & Friends","letter":"We''re deeply grateful to celebrate this day with the people who have shaped our lives. This website will share all wedding details as the date gets closer, and we can\\u2019t wait to make lasting memories together.","signoff":"Kyle & Nicole","image":"\\/images\\/wedding\\/uploads\\/welcome-image-20260414185638.jpg","imageFocusX":50,"imageFocusY":50},"timeline":{"heading":"The Big Day","dateAccent":"12 September, 2026","items":[{"time":"2:00 PM","title":"Ceremony","description":"Join us as we say \\u201cI do.\\u201d"},{"time":"3:30 PM","title":"Photos","description":"Family portraits and couple photos."},{"time":"5:00 PM","title":"Dinner","description":"A tasty 3 course meal."},{"time":"7:00 PM","title":"Dancing","description":"The party starts!"}]},"story":{"heading":"Our Story","accent":"March 2016","text":"Our paths crossed at a mutual friend\\u2019s gathering, and what began as a simple hello became years of laughter, support, and adventure. Through every season of life, we have built a home in each other. We are so excited for this next chapter and thankful to share it with everyone we love.","image":"\\/images\\/wedding\\/uploads\\/story-image-20260414190159.jpg","imageFocusX":50,"imageFocusY":32},"details":{"venue":{"name":"Kingfisher Country Estate","address":"Templepatrick, Ballyclare BT39 0GA","blurb":"Ceremony and reception will both be held onsite. Please arrive 20 minutes early for seating.&nbsp;"},"travel":"For guests traveling in, we recommend staying near Downtown City. A room block is reserved at The Magnolia House and Riverfront Hotel through May 20, 2027.&nbsp;","faqs":[{"question":"Is there a dress code?","answer":"Formal attire requested. Think cocktail dresses and suits."},{"question":"Can I bring a plus one?","answer":"Your invitation indicates the number of seats reserved for your party."},{"question":"Are children invited?","answer":"We adore your little ones, but this will be an adults-focused evening."},{"question":"Is there a vegetarian option?","answer":"Yes, there is plenty of grass around the venue to graze on."}],"image":"\\/images\\/wedding\\/uploads\\/details-image-20260414190238.jpg","imageFocusX":50,"imageFocusY":50},"gallery":{"heading":"Photo''s of us across the years","items":[{"image":"\\/images\\/wedding\\/uploads\\/gallery-items-0-image-20260415132202.jpeg","imageFocusX":50,"imageFocusY":34},{"image":"\\/images\\/wedding\\/uploads\\/gallery-items-1-image-20260415132222.jpeg","imageFocusX":50,"imageFocusY":42},{"image":"\\/images\\/wedding\\/uploads\\/gallery-items-2-image-20260415133037.jpeg","imageFocusX":50,"imageFocusY":34},{"image":"\\/images\\/wedding\\/uploads\\/gallery-items-3-image-20260415133059.jpeg","imageFocusX":50,"imageFocusY":50},{"image":"\\/images\\/wedding\\/uploads\\/gallery-items-4-image-20260415133404.jpeg","imageFocusX":50,"imageFocusY":74},{"image":"\\/images\\/wedding\\/uploads\\/gallery-items-6-image-20260415133428.jpeg","imageFocusX":50,"imageFocusY":94},{"image":"\\/images\\/wedding\\/uploads\\/gallery-items-7-image-20260415133439.jpeg","imageFocusX":50,"imageFocusY":56},{"image":"\\/images\\/wedding\\/uploads\\/gallery-items-7-image-20260415135631.jpeg","imageFocusX":50,"imageFocusY":48}]},"cta":{"title":"Ready to Celebrate With Us?","text":"RSVP online in just a few moments using your invitation code.","buttonLabel":"Go to RSVP"},"theme":{"primary_color":"#22363A","button_color":"#22363A"},"section_visibility":{"welcome":true,"story":true,"timeline":true,"venue":true,"travel":true,"menu":true,"faqs":true,"gallery":true}}', '2026-02-25 18:31:17', '2026-04-15 13:56:44');
INSERT INTO `site_settings` (`site_id`, `key`, `value`, `created_at`, `updated_at`) VALUES (@site_id, 'rsvp_settings', '{"meal_mode":"set_menu","menu_heading":"Wedding Menu","menu_intro":"We cannot wait to share a beautiful meal with you.","set_menu_description":"A chef-curated set menu will be served for all attending guests.","menu_note_title":"Dining Notes","menu_note_text":"<p>If you have dietary requirements, please let us know in the RSVP. All tables will include a bottle of red and white wine.<\\/p>","meal_options":["Seabass","Beef Fillet","Wild Mushroom Risotto"],"kids_menu_enabled":false,"kids_menu_items":[],"menu_courses":[{"id":"starter","name":"Starter","items":[{"title":"Vegetable Broth","description":"Seasonal vegetable broth, served with fresh warm breads."}]},{"id":"main","name":"Main","items":[{"title":"Roast Sirloin of Beef","description":"Served with a Yorkshire pudding with a rich pan gravy or peppercorn sauce."}]},{"id":"dessert","name":"Dessert","items":[{"title":"Dessert Trio","description":"Seasonal trio of mini desserts."}]}]}', '2026-02-25 18:31:17', '2026-04-15 14:23:25');
